const input = $json.body ?? $json;
const jobId = input.jobId;
if (!jobId || !/^[0-9a-f-]{36}$/i.test(jobId)) throw new Error('Invalid jobId');
return [{json: {...input, jobId}}];

const configuration = $('Duration Configuration').first().json;
const rows = configuration.jobRows;
const job = Array.isArray(rows) ? rows[0] : rows;
if (!job?.brief_json) throw new Error('Job not found or missing brief_json');
const brief = job.brief_json;
const request = $('Validate').first().json;
const requestedDuration = Number(request.requestedDuration ?? brief.duration);
const durationRanges = configuration.durationRanges;
const range = durationRanges[requestedDuration];
if (!range) throw new Error('INVALID_REQUESTED_DURATION');
const [minimumDuration, maximumDuration] = range;
const voiceRates = { 'Warm narrator': 140, 'Studio neutral': 132, 'Energetic guide': 132 };
const voiceWordsPerMinute = voiceRates[String(brief.voiceTone || '').trim()] || 140;
const targetWords = Math.round(requestedDuration * voiceWordsPerMinute / 60);
const defaultSceneCount = Math.ceil(requestedDuration / 5);
const sceneCount = Math.max(6, Math.min(20, Number(brief.sceneCount ?? defaultSceneCount)));
const sceneCountMin = Math.max(6, Math.floor(defaultSceneCount * 0.7));
const sceneCountMax = Math.min(24, Math.ceil(defaultSceneCount * 1.3));
const textProvider = job.text_provider || brief.textProvider || $env.AI_TEXT_PROVIDER || 'cloudflare';
const textModel = job.text_model || brief.textModel || (textProvider === 'gemini' ? ($env.GEMINI_TEXT_MODEL || 'gemini-2.5-flash') : textProvider === 'cloudflare' ? ($env.CLOUDFLARE_TEXT_MODEL || '@cf/meta/llama-3.1-8b-instruct') : null);
if (!textModel) throw new Error('TEXT_MODEL_REQUIRED_FOR_PROVIDER: ' + textProvider);
const fullScenes = 'Return a fullScenes sequence with complete narration and visual detail. Return one valid JSON object only. No markdown fences. No headings. No extra prose.';
const prompt = 'Create a complete short-form video script as JSON for topic: ' + brief.topic + '. Style: ' + brief.contentStyle + '. Visual style: ' + brief.visualStyle + '. The full video duration has an estimated narration range of ' + minimumDuration + '-' + maximumDuration + ' seconds. Use about ' + targetWords + ' words as guidance, not as an exact requirement. ' + fullScenes + ' Return title, description, hashtags, fullNarration, and ' + sceneCount + ' scenes. Each scene needs narration, caption, imagePrompt, motion, and transition. Optionally include generic delivery metadata as one of dramatic, pause, or warm only when it is meaningful; omit it otherwise. Do not add provider-specific syntax or force cues. Do not repeat filler phrases.';
return [{ json: { jobId: job.id, requestedDuration, minimumDuration, maximumDuration, voiceWordsPerMinute, targetWords, sceneCount, sceneCountMin, sceneCountMax, prompt, textProvider, textModel, credentialSource: job.credential_source || 'environment', routingVersion: job.provider_configuration_version || '1', audio_mode: job.audio_mode || 'automatic', wordCountRevisionAttempt: Number(request.wordCountRevisionAttempt || 0), leaseToken: request.leaseToken } }];

const response = $input.first().json;
const raw = response.result ?? '';
let text = typeof raw === 'string' ? raw : JSON.stringify(raw);
text = text.replace(/^\s*\x60\x60\x60(?:json)?\s*/i, '');
const closeFenceIdx = text.lastIndexOf('\x60\x60\x60');
if (closeFenceIdx >= 0) text = text.substring(0, closeFenceIdx);
let content;
try { content = JSON.parse(text.trim()); } catch { throw new Error('Invalid AI JSON'); }
const ctx = $('Build Prompt').first().json;
if (!Array.isArray(content.scenes) && Array.isArray(content.fullScenes)) content.scenes = content.fullScenes;
if (!content.title || !content.description || !Array.isArray(content.scenes) || !content.scenes.length) throw new Error('AI response is missing required script fields');
if (content.scenes.length < ctx.sceneCountMin || content.scenes.length > ctx.sceneCountMax) throw new Error('SCENE_COUNT_OUT_OF_RANGE');
const motions = ['zoom_in','zoom_out','pan_left','pan_right','pan_up','pan_down'];
const transitions = ['fade','crossfade','slide_left','slide_right'];
const deliveryCues = ['dramatic', 'pause', 'warm'];
content.scenes = content.scenes.map((scene, index) => { const delivery = typeof scene.delivery === 'string' ? scene.delivery.trim() : ''; return { index: index + 1, narration: String(scene.narration ?? '').trim(), caption: String(scene.caption ?? '').trim(), imagePrompt: String(scene.imagePrompt ?? '').trim(), durationSeconds: Number(scene.durationSeconds) || 5, motion: motions.includes(scene.motion) ? scene.motion : 'zoom_in', transition: transitions.includes(scene.transition) ? scene.transition : 'crossfade', ...(deliveryCues.includes(delivery) ? { delivery } : {}) }; });
if (content.scenes.some(scene => !scene.narration || !scene.caption || !scene.imagePrompt)) throw new Error('SCENE_CONTENT_REQUIRED');
const narration = content.scenes.map(scene => scene.narration).join(' ').trim();
const wordCount = narration.split(/\s+/).filter(Boolean).length;
const normalizedNarration = narration.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
const repeatedFiller = /\b(stay present and move forward with clarity)\b(?:.*\b\1\b){2}/i.test(narration) || new Set(normalizedNarration.match(/\b\w+(?: \w+){4}\b/g) || []).size < Math.max(1, Math.floor(wordCount / 12));
if (repeatedFiller) throw new Error('REPEATED_FILLER_NARRATION');
const estimatedDurationSeconds = Math.round((wordCount / ctx.voiceWordsPerMinute * 60) * 100) / 100;
const audioMode = ctx.audio_mode || 'automatic';
const durationAccepted = audioMode === 'custom_audio' || (estimatedDurationSeconds >= ctx.minimumDuration && estimatedDurationSeconds <= ctx.maximumDuration);
if (durationAccepted) {
  let allocated = 0;
  content.scenes = content.scenes.map((scene, index) => {
    const durationSeconds = index === content.scenes.length - 1 ? Math.round((estimatedDurationSeconds - allocated) * 100) / 100 : Math.round((estimatedDurationSeconds / content.scenes.length) * 100) / 100;
    allocated += durationSeconds;
    return { ...scene, durationSeconds };
  });
}
content.fullNarration = narration;
content.durationValidation = { requestedDuration: ctx.requestedDuration, minimumDuration: ctx.minimumDuration, maximumDuration: ctx.maximumDuration, estimatedDurationSeconds, wordCount, voiceWordsPerMinute: ctx.voiceWordsPerMinute };
return [{ json: { jobId: ctx.jobId, content, wordCount, estimatedDurationSeconds, minimumDuration: ctx.minimumDuration, maximumDuration: ctx.maximumDuration, requestedDuration: ctx.requestedDuration, wordCountRevisionAttempt: ctx.wordCountRevisionAttempt, wordCountValid: durationAccepted, audio_mode: audioMode, leaseToken: ctx.leaseToken } }];

const original = $input.first().json;
const jobId = original.jobId;
const content = original.content;

const options = {
  method: 'PATCH',
  url: $env.SUPABASE_URL + '/rest/v1/video_jobs?id=eq.' + jobId,
