    progress: 25,
    script_json: content,
    updated_at: new Date().toISOString()
  }),
  json: true
};

const response = await this.helpers.httpRequest(options);
return [{ json: { ...original, ...response.data, audio_mode: original.audio_mode || 'automatic' } }];

