return [{json: {...input, jobId, stage, itemKey, stageHashInput: canonical, workerId: input.workerId, leaseToken: input.leaseToken, attemptNumber: Number(input.attemptNumber), pipelineRevision: Number(input.pipelineRevision)}}];

const {stageHashInput, ...context} = $('Hash Stage Input').first().json;
const state = $json.state;
const stageRunId = $json.stage_run_id;
const stateSet = ['STARTED','CACHED_SUCCESS','RUNNING','FAILED','INPUT_HASH_MISMATCH','INVALID_ITEM_KEY','UNKNOWN_OUTCOME'];
if (typeof state !== 'string' || stateSet.indexOf(state) === -1) throw new Error('WF04_LEDGER_STATE_UNSUPPORTED: ' + state);
