const revisionPrompt = '\n\nREVISION ATTEMPT ' + newAttempt + '. The current estimate is ' + previous.estimatedDurationSeconds + ' seconds; the acceptable estimated range is ' + context.minimumDuration + '-' + context.maximumDuration + ' seconds. Rewrite the narration naturally while preserving useful scene detail and avoiding repeated filler.\n\nPREVIOUS NARRATION:\n' + (previous.content?.fullNarration || '(none)');
return [{ json: { ...context, ...leaseContext, wordCountRevisionAttempt: newAttempt, prompt: context.prompt + revisionPrompt } }];

